regions=[]
for r in range(R):
    for c in range(C):
        if test[r][c]==bg and not seen[r][c]:
            q=deque([(r,c)]); seen[r][c]=True; cells=[]
            while q:
                a,b=q.popleft(); cells.append((a,b))
                for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                    na,nb=a+dr,b+dc
