                        seen[na][nb]=True; q.append((na,nb))
            edges=set()
            for a,b in cells:
                if a==0: edges.add('T')
                if a==R-1: edges.add('B')
                if b==0: edges.add('L')
                if b==C-1: edges.add('R')
            regions.append((len(cells), sorted(edges), cells if len(cells)<30 else f'{len(cells)} cells'))
for reg in sorted(regions, key=lambda x:x[0]):
